import{_ as a,c as t,al as i,o as r}from"./chunks/framework.CbalHM_x.js";const y=JSON.parse('{"title":"Battery-Chemistry Overview","description":"","frontmatter":{},"headers":[],"relativePath":"en/power_systems/battery_chemistry.md","filePath":"en/power_systems/battery_chemistry.md"}'),l={name:"en/power_systems/battery_chemistry.md"};function o(n,e,s,h,c,d){return r(),t("div",null,e[0]||(e[0]=[i('<h1 id="battery-chemistry-overview" tabindex="-1">Battery-Chemistry Overview <a class="header-anchor" href="#battery-chemistry-overview" aria-label="Permalink to &quot;Battery-Chemistry Overview&quot;">​</a></h1><p>This section provides a comparative overview of several different battery types (in particular LiPo and Li-Ion) and some useful battery glossary terms.</p><h2 id="lipo-vs-li-ion" tabindex="-1">LiPo vs Li-Ion <a class="header-anchor" href="#lipo-vs-li-ion" aria-label="Permalink to &quot;LiPo vs Li-Ion&quot;">​</a></h2><ul><li>Li-Ion batteries have a higher energy density than Lipo battery packs but that comes at the expense of lower discharge rates and increased battery cost.</li><li>LiPo batteries are readily available and can withstand higher discharge rates that are common in multi-rotor aircraft.</li><li>The choice needs to be made based on the vehicle and the mission being flown. If absolute endurance is the aim then there is more of a benefit to flying to a Li-Ion battery but similarly, more caution needs to be taken. As such, the decision should be made based on the factors surrounding the flight.</li></ul><h3 id="lipo" tabindex="-1">LiPo <a class="header-anchor" href="#lipo" aria-label="Permalink to &quot;LiPo&quot;">​</a></h3><p>Advantages:</p><ul><li>Very common</li><li>Wide range of sizes, capacities and voltages</li><li>Inexpensive</li><li>High discharge rates relative to capacity (high C ratings)</li><li>Higher charge rates</li></ul><p>Disadvantages:</p><ul><li>Low (relative) energy density</li><li>Quality can vary given abundance of suppliers</li></ul><h3 id="li-ion" tabindex="-1">Li-Ion <a class="header-anchor" href="#li-ion" aria-label="Permalink to &quot;Li-Ion&quot;">​</a></h3><p>Advantages:</p><ul><li>Much higher energy density (up to 60% higher)</li></ul><p>Disadvantages:</p><ul><li>Not as common</li><li>Much more expensive</li><li>Not as widely available in large sizes and configurations</li><li>All cells are relatively small so larger packs are made up of many cells tied in series and parallel to create the required voltage and capacity</li><li>Lower discharge rates relative to battery size (C rating)</li><li>More difficult to adapt to vehicles that require high currents</li><li>Lower charging rates (relative to capacity)</li><li>Requires more stringent temperature monitoring during charge and discharge</li><li>Requires settings changes on the ESC to utilize max capacity (&quot;standard&quot; ESC low voltage settings are too high).</li><li>At close-to-empty the voltage of the battery is such that a ~3V difference is possible between a Lipo to Li-ion (while using a 6S battery). This could have implications on thrust expectations.</li></ul><h2 id="c-ratings" tabindex="-1">C Ratings <a class="header-anchor" href="#c-ratings" aria-label="Permalink to &quot;C Ratings&quot;">​</a></h2><ul><li>A C rating is simply a multiple of the stated capacity of any battery type.</li><li>A C rating is relevant (and differs) for both charge and discharge rates. <ul><li>For example, a 2000 mAh battery (irrespective of voltage) with a 10C discharge rate can safely and continuously discharge 20 amps of current (2000/1000=2Ah x 10C = 20 amps).</li></ul></li><li>C Ratings are always given by the manufacturer (often on the outside of the battery pack). While they can actually be calculated, you need several pieces of information, and to measure the internal resistance of the cells.</li><li>LiPo batteries will always have a higher C rating than a Li-Ion battery. This is due to chemistry type but also to the internal resistance per cell (which is due to the chemistry type) leading to higher discharge rates for LiPo batteries.</li><li>Following manufacturer guidelines for both charge and discharge C ratings is very important for the health of your battery and to operate your vehicle safely (i.e. reduce fires, “puffing” packs and other suboptimal states during charging and discharging).</li></ul><h2 id="energy-density" tabindex="-1">Energy Density <a class="header-anchor" href="#energy-density" aria-label="Permalink to &quot;Energy Density&quot;">​</a></h2><ul><li>Energy density is how much energy is able to be stored relative to battery weight. It is generally measured and compared in Watt Hour per Kilogram (Wh/Kg). <ul><li>Watt-hours are simply calculated by taking the nominal (i.e. not the fully charged voltage) multiplied by the capacity, e.g. 3.7v X 5 Ah = 18.5Wh. If you had a 3 cell battery pack your pack would be 18.5Wh X 3 = 55 Wh of stored energy.</li></ul></li><li>When you take battery weight into account you calculate energy density by taking the watt-hours and dividing them by weight. <ul><li>E.g. 55 Wh divided by (battery weight in grams divided by 1000). Assuming this battery weighed 300 grams then 55/(300/1000)=185 Wh/Kg.</li></ul></li><li>This number 185 Wh/Kg would be on the very high-end for a LiPo battery. A Li-Ion battery on the other hand can reach 260 Wh/Kg, meaning per kilogram of battery onboard you can carry 75 more watt-hours. <ul><li>If you know how many watts your vehicle takes to fly (which a battery current module can show you), you can equate this increased storage at no additional weight into increased flight time.</li></ul></li></ul>',18)]))}const g=a(l,[["render",o]]);export{y as __pageData,g as default};
